#[test]fn sqlite_snapshot_en1993_all_entities_and_independent_sqlite_edit(){use std::io::Write;use std::process::{Command,Stdio};let s=fixture();let d=project(&s);assert_eq!(d.tables.len(),39);assert_eq!(restore(&d).unwrap(),s);let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const j=d.query('SELECT bolt_rows,bolts_per_row,shear_planes,friction_surfaces FROM en1993_joint').get();if(Object.values(j).some(n=>n!==4294967295)||d.query('SELECT category FROM en1993_fatigue_detail').get().category!==255)throw Error('nativewidths');d.query(\"UPDATE en1993_member SET analysis='Plastic'\").run();await Bun.write(Bun.stdout,d.serialize());d.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let back=restore(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=s;expected.members[0].analysis = semio_s_artifact_norm_en1993_model::AnalysisKind::Plastic;assert_eq!(back,expected);}
#[test]fn sqlite_snapshot_en1993_ownership_order_width_and_ieee_guards(){let d=project(&fixture());for table in["en1993_joint_action","en1993_fatigue_band","en1993_cold_formed_action","en1993_plated_action","en1993_tension_action","en1993_tower_action","en1993_pile_action","en1993_crane_action"]{for(index,value)in[(1,999),(2,2)]{let mut bad=d.clone();bad.table_mut(table).unwrap().rows[0].values[index]=SqliteValue::Integer(value);assert!(restore(&bad).is_err());}}for(table,index,maximum)in[("en1993_joint",8,4294967295),("en1993_joint",9,4294967295),("en1993_joint",14,4294967295),("en1993_joint",25,4294967295),("en1993_fatigue_detail",5,255),("en1993_bridge_fatigue",8,255)]{for value in[-1,maximum+1]{let mut bad=d.clone();bad.table_mut(table).unwrap().rows[0].values[index]=SqliteValue::Integer(value);assert!(restore(&bad).is_err());}}let mut bad=d.clone();bad.table_mut("en1993_document").unwrap().rows[0].values[1]=SqliteValue::Text("unknown".into());assert!(restore(&bad).is_err());let mut bad=d.clone();bad.table_mut("en1993_material").unwrap().rows[0].values[5]=SqliteValue::Real(99.0);assert!(restore(&bad).is_err());let mut bad=d;let t=bad.table_mut("en1993_member").unwrap();t.sql=t.sql.replace("analysis TEXT NOT NULL","analysis TEXT");assert!(restore(&bad).is_err());}
#[test]fn sqlite_snapshot_en1993_limits_and_large_copy_cancellation(){let mut s=fixture();for limits in[SqliteDatabaseLimits{max_rows:1,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_value_bytes:16,..SqliteDatabaseLimits::default()}]{assert!(original_owners::with_sqlite_recipient(limits,&mut |_|true,|sqlite_control|s.to_sqlite_database(sqlite_control)).is_err());}assert!(original_owners::with_sqlite_recipient(SqliteDatabaseLimits::default(),&mut |_|false,|sqlite_control|s.to_sqlite_database(sqlite_control)).is_err());let d=project(&s);assert!(original_owners::with_sqlite_recipient(SqliteDatabaseLimits::default(),&mut |_|false,|sqlite_control|En1993Snapshot::from_sqlite_database(&d, sqlite_control)).is_err());assert!(original_owners::with_sqlite_recipient(SqliteDatabaseLimits{max_value_bytes:16,..SqliteDatabaseLimits::default()},&mut |_|true,|sqlite_control|En1993Snapshot::from_sqlite_database(&d, sqlite_control)).is_err());s.materials[0].grade="地".repeat(40000);let mut stopped=false;assert!(original_owners::with_sqlite_recipient(SqliteDatabaseLimits::default(),&mut |p|{if p.phase==SqliteSnapshotPhase::ProjectSnapshot&&p.completed>0{stopped=true;false}else{true}},|sqlite_control|s.to_sqlite_database(sqlite_control)).is_err());assert!(stopped);for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{assert!(s.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:65536,..SqliteDatabaseLimits::default()})).is_err());}}
#[test]fn sqlite_snapshot_en1993_actual_bare_erased_encodings_and_coordinates(){let s=fixture();let p=store::bare_artifact_codec::<En1993Snapshot,semio_s_artifact_norm_en1993_mutations::En1993Mutation>(semio_s_artifact_norm_en1993_model::EN1993_DOCUMENT_SCHEMA).snapshot_sqlite.unwrap();assert_eq!(p.snapshot_type,Some(std::any::TypeId::of::<En1993Snapshot>()));let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.norm.en1993".into(),standard:"1".into(),subset:"*".into()};for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(<En1993Snapshot as pack::snapshot::ArtifactPack>::encode_pack(&s)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(<En1993Snapshot as pack::snapshot::ArtifactDsl>::print_dsl(&s))};let d=original_owners::with_decoding(|native_owner|(p.export)(semio_s_artifact_norm_en1993_model::EN1993_DOCUMENT_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap().value;assert_eq!(project(&restore(&d).unwrap()),project(&s));assert_eq!(original_owners::with_encoding(|native_owner|(p.import)(semio_s_artifact_norm_en1993_model::EN1993_DOCUMENT_SCHEMA,&dialect, &mut Some(d),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap().value,payload);}let d=project(&s);for(artifact_kind,standard,subset)in[("s.norm.other","1","*"),("s.norm.en1993","v1","*"),("s.norm.en1993","1","named")]{let wrong=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:artifact_kind.into(),standard:standard.into(),subset:subset.into()};assert!(s.validate_sqlite_snapshot_subset(&wrong,&d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}}
