fn sqlite_snapshot_en1993_borrowed_complete_gate_copied_limits_exact_and_one_short(){
 use store::{os_store::serialization::ArtifactSqliteSnapshotHost as _,sqlite_snapshot::*};
 let contract:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🎛️semantic.json")).unwrap();let defaults=SqliteDatabaseLimits::default();
 for case in contract["cases"].as_array().unwrap(){let source=norm_complete_source(case);let extent=norm_independent_complete_extent(&source);assert_eq!(extent["rows"],case["rows"]);assert_eq!(extent["valueBytes"],case["valueBytes"]);assert_eq!(extent["schemaBytes"],contract["schemaBytes"]);assert_eq!(extent["tableWidths"],contract["tableWidths"]);
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::io::IoPayload::Binary(<En1993Snapshot as pack::snapshot::ArtifactPack>::encode_pack_with(&source,&Default::default()).unwrap()),SnapshotEncoding::Text=>store::io::IoPayload::Text(<En1993Snapshot as pack::snapshot::ArtifactDsl>::print_dsl(&source))};
 for(role,total)in[("rows",case["rows"].as_u64().unwrap()as usize),("bytes",case["valueBytes"].as_u64().unwrap()as usize),("schema",contract["schemaBytes"].as_u64().unwrap()as usize),("tables",39),("columns",162)]{for accepted in[true,false]{let maximum=total-usize::from(!accepted);let limits=match role{"rows"=>SqliteDatabaseLimits{max_rows:maximum,..defaults},"bytes"=>SqliteDatabaseLimits{max_value_bytes:maximum,..defaults},"schema"=>SqliteDatabaseLimits{max_schema_bytes:maximum,..defaults},"tables"=>SqliteDatabaseLimits{max_tables:maximum,..defaults},"columns"=>SqliteDatabaseLimits{max_columns:maximum,..defaults},_=>unreachable!()};let result=store::decode_sqlite_snapshot_record_native(&payload,<En1993Snapshot as pack::snapshot::ArtifactDsl>::envelope_id(),En1993Snapshot::__dsl_spec_producer(),|record, snapshot_output, native,_body| { let constructed: Result<_, semio_framework_value::ValueError> = (|| {semio_s_artifact_norm_en1993_io::sqlite::snapshot::admission::admit(record,native,limits)})(); *snapshot_output = Some(constructed?); Ok(()) },&mut SqliteSnapshotControl::new(&mut |_|true,defaults));assert_eq!(result.is_ok(),accepted,"borrowed full CST before typed ownership {encoding:?} {role} {limits:?}");}}}
 source.retire_sqlite_snapshot();}
}

